#include <linux/cred.h>
#include <linux/sched.h>
#include <linux/uaccess.h>
#include <linux/errno.h>

int check_credential_permissions(struct ucred *creds)
{
    struct cred *current_cred = current_cred();
    struct cred *target_cred = get_cred(creds);

    if (!target_cred)
        return -EINVAL;

    if (current_cred->uid != target_cred->uid ||
        current_cred->gid != target_cred->gid) {
        put_cred(target_cred);
        if (!capable(CAP_ADMIN))
            return -EPERM;
    }

    put_cred(target_cred);
    return 0;
}
